import java.util.Scanner;

public class Main {
    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long distSq(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    static long dot(Point a, Point b, Point c) {
        // Dot product of (b - a) and (c - a)
        return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
    }

    static long dotVec(Point v1, Point v2) {
        return v1.x * v2.x + v1.y * v2.y;
    }

    static long cross(Point a, Point b, Point c) {
        // 2D cross product of (b - a) x (c - a)
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLong()) return;

        Point[] p = new Point[8];
        for (int i = 1; i <= 7; i++) {
            p[i] = new Point(sc.nextLong(), sc.nextLong());
        }

        // Condição 1: O ângulo ∠P2P1P3 é agudo (vértice em P1)
        if (dot(p[1], p[2], p[3]) <= 0) {
            System.out.println("N");
            return;
        }

        // Condição 2: Os segmentos P1P2 e P1P3 têm o mesmo comprimento
        if (distSq(p[1], p[2]) != distSq(p[1], p[3])) {
            System.out.println("N");
            return;
        }

        // Condição 3: Os pontos P2, P3, P4 e P5 são colineares
        if (cross(p[2], p[3], p[4]) != 0 || cross(p[2], p[3], p[5]) != 0) {
            System.out.println("N");
            return;
        }

        // Condição 4: Os pontos médios dos segmentos P2P3 e P4P5 são coincidentes
        if (p[2].x + p[3].x != p[4].x + p[5].x || p[2].y + p[3].y != p[4].y + p[5].y) {
            System.out.println("N");
            return;
        }

        // Condição 5: O segmento P2P3 tem comprimento maior que o segmento P4P5
        if (distSq(p[2], p[3]) <= distSq(p[4], p[5])) {
            System.out.println("N");
            return;
        }

        // Condição 6: Os segmentos P4P6 e P5P7 são perpendiculares ao segmento P2P3
        Point v23 = new Point(p[3].x - p[2].x, p[3].y - p[2].y);
        Point v46 = new Point(p[6].x - p[4].x, p[6].y - p[4].y);
        Point v57 = new Point(p[7].x - p[5].x, p[7].y - p[5].y);

        if (dotVec(v46, v23) != 0 || dotVec(v57, v23) != 0) {
            System.out.println("N");
            return;
        }

        // Condição 7: Os segmentos P4P6 e P5P7 têm o mesmo comprimento
        if (distSq(p[4], p[6]) != distSq(p[5], p[7])) {
            System.out.println("N");
            return;
        }

        // Condição 8: Os pontos P1 e P6 devem estar separados pela reta que contém o segmento P2P3
        long cp1 = cross(p[2], p[3], p[1]);
        long cp6 = cross(p[2], p[3], p[6]);

        boolean separated = (cp1 > 0 && cp6 < 0) || (cp1 < 0 && cp6 > 0);
        if (!separated) {
            System.out.println("N");
            return;
        }

        System.out.println("S");
    }
}
```

